declare(strict_types=1);
session_start();$root=dirname(__DIR__,3);$cfg=require $root.'/config.php';date_default_timezone_set($cfg['timezone']??'America/Argentina/Buenos_Aires');if(empty($_SESSION['user'])||($_SESSION['user']['role']??'')!=='admin'){http_response_code(403);exit('Esta sección es exclusiva para administradores.');}$db=new PDO('mysql:host='.$cfg['db_host'].';dbname='.$cfg['db_name'].';charset=utf8mb4',$cfg['db_user'],$cfg['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$_SESSION['csrf']??=bin2hex(random_bytes(24));function pe($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}$catalog=['dashboard'=>'Panel general','clients'=>'Clientes','partners'=>'Arquitectos y constructoras','products'=>'Productos, precios y stock','projects'=>'Proyectos y presupuestos','technical_projects'=>'Proyectos técnicos','payments'=>'Cobros y pagos','receipts'=>'Recibos','billing'=>'Facturación (próximamente)'];$a=$_GET['a']??'edit_profile';if($a==='update_profile'){$token=$_POST['csrf']??'';if(!hash_equals($_SESSION['csrf'],$token)){http_response_code(419);exit('Solicitud vencida.');}$id=(int)($_POST['profile_id']??0);$name=trim($_POST['name']??'');$area=$_POST['area']??'';if(!$id||$name===''||!in_array($area,['comercial','tecnico','administracion','gerencial'],true))exit('Datos inválidos.');$db->beginTransaction();try{$db->prepare('UPDATE user_profiles SET name=?,area=? WHERE id=?')->execute([$name,$area,$id]);$db->prepare('DELETE FROM profile_module_permissions WHERE profile_id=?')->execute([$id]);$ins=$db->prepare('INSERT INTO profile_module_permissions(profile_id,module_key,can_view,can_manage) VALUES(?,?,?,?)');foreach($catalog as $key=>$label){$view=!empty($_POST['permissions'][$key]['view']);$manage=!empty($_POST['permissions'][$key]['manage']);if($manage)$view=true;$ins->execute([$id,$key,(int)$view,(int)$manage]);}$db->commit();$_SESSION['msg']='Perfil actualizado.';header('Location:?a=users');exit;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}
$id=(int)($_GET['id']??0);$s=$db->prepare('SELECT * FROM user_profiles WHERE id=?');$s->execute([$id]);$profile=$s->fetch();if(!$profile){http_response_code(404);exit('Perfil inexistente.');}$s=$db->prepare('SELECT module_key,can_view,can_manage FROM profile_module_permissions WHERE profile_id=?');$s->execute([$id]);$perms=[];foreach($s as $p)$perms[$p['module_key']]=['view'=>(bool)$p['can_view'],'manage'=>(bool)$p['can_manage']];require_once $root.'/app/Core/UnifiedSidebar.php';?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Editar perfil · Punto ERP</title><style><?=erpSidebarCss()?>body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.45 system-ui}.main{margin-left:var(--sidebar);padding:32px 4%;max-width:1200px}.card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:24px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}label{display:block;font-weight:700;margin-bottom:7px}input[type=text],select{width:100%;padding:12px;border:1px solid #cbd1d7;border-radius:9px;font:inherit}.permissions{width:100%;border-collapse:collapse;margin-top:22px}.permissions th,.permissions td{padding:13px 10px;border-bottom:1px solid var(--line);text-align:left}.permissions th{color:var(--muted);font-size:12px;text-transform:uppercase}.permissions th:not(:first-child),.permissions td:not(:first-child){text-align:center;width:110px}.permissions input{width:20px;height:20px}.technical{background:#fff7f1}.technical td:first-child{font-weight:800}.btn{display:inline-block;border:0;border-radius:9px;padding:11px 17px;background:var(--o);color:#fff;text-decoration:none;font-weight:750;cursor:pointer}.btn.light{background:#edf0f3;color:var(--ink)}.actions{display:flex;gap:10px;margin-top:22px}@media(max-width:900px){.main{margin-left:0;padding:20px 14px}.grid{grid-template-columns:1fr}.card{overflow:auto}}</style></head><body><?php erpSidebar('users');?><main class="main"><div class="card"><h1>Editar perfil</h1><form method="post" action="?a=update_profile"><input type="hidden" name="csrf" value="<?=pe($_SESSION['csrf'])?>"><input type="hidden" name="profile_id" value="<?=$id?>"><div class="grid"><div><label>Nombre del perfil</label><input type="text" name="name" value="<?=pe($profile['name'])?>" required></div><div><label>Área</label><select name="area"><?php foreach(['comercial'=>'Comercial','tecnico'=>'Técnico','administracion'=>'Administración','gerencial'=>'Gerencial'] as $k=>$v):?><option value="<?=$k?>" <?=$profile['area']===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></div></div><table class="permissions"><thead><tr><th>Módulo</th><th>Ver</th><th>Gestionar</th></tr></thead><tbody><?php foreach($catalog as $key=>$label):$p=$perms[$key]??['view'=>false,'manage'=>false];?><tr class="<?=$key==='technical_projects'?'technical':''?>"><td><?=pe($label)?><?=$key==='technical_projects'?'<br><small style="font-weight:400;color:#6e7781">Vista de obra sin precios + asignación de equipo técnico</small>':''?></td><td><input type="checkbox" name="permissions[<?=$key?>][view]" value="1" <?=$p['view']?'checked':''?>></td><td><input type="checkbox" name="permissions[<?=$key?>][manage]" value="1" <?=$p['manage']?'checked':''?> <?=$key==='billing'?'disabled':''?>></td></tr><?php endforeach;?></tbody></table><div class="actions"><button class="btn" type="submit">Guardar cambios</button><a class="btn light" href="?a=users">Cancelar</a></div></form></div></main></body></html>